#!/bin/bash
# Fill packaging/homebrew/xcfs.rb in for a tagged release: the tag's archive URL and its sha256, computed from the
# tarball GitHub serves for the tag (it is generated by GitHub, so it is downloaded rather than built here).
#
#   scripts/homebrew-formula.sh <version>        e.g. 0.2.0, after `git tag v0.2.0 && git push origin v0.2.0`
#
# Then copy the formula into the tap repository as Formula/xcfs.rb.
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.." && pwd -P)
VERSION=${1:?usage: scripts/homebrew-formula.sh <version>}
HOME_URL=$(sed -n 's/^  homepage "\(.*\)"$/\1/p' "$ROOT/packaging/homebrew/xcfs.rb")
URL="$HOME_URL/archive/refs/tags/v$VERSION.tar.gz"
grep -q "^VERSION = \"$VERSION\"" "$ROOT/lib/xcfs/__init__.py" || { echo "lib/xcfs/__init__.py is not at $VERSION" >&2; exit 2; }
SHA=$(curl -fsSL "$URL" | shasum -a 256 | cut -d' ' -f1)
sed -i '' -e "s#^  url \".*\"#  url \"$URL\"#" -e "s#^  sha256 \".*\"#  sha256 \"$SHA\"#" "$ROOT/packaging/homebrew/xcfs.rb"
echo "packaging/homebrew/xcfs.rb: $URL"
echo "sha256 $SHA"
